#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate direct MicroPython native decorators from the portable GPU driver."""
import ast
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'software/kagura_fb/kagura_fb.py'
text=path.read_text(encoding='utf-8');lines=text.splitlines()
tree=ast.parse(text)
out=['# SPDX-License-Identifier: Apache-2.0',
     '# Generated by tools/gen-native-commands.py; do not hand-edit.',
     '# Direct decorators are compiler directives; runtime aliases do not work.',
     'import micropython','from kagura_fb import Device, _exclusive','']
for node in tree.body:
    if isinstance(node,ast.FunctionDef) and node.name in ('_put16','_put32'):
        out+=['@micropython.native']+lines[node.lineno-1:node.end_lineno]+['']
out+=['class NativeDevice(Device):','    accelerated = True','']
cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Device')
selected=('_read','_write','_expired','_idle','submit','_execute','wait','fill_rect','copy_rect',
          'write_bytes','read_into','palette','present','fence')
for node in cls.body:
    if isinstance(node,ast.FunctionDef) and node.name in selected:
        if node.name == '_execute':
            out += '''    @_exclusive
    @micropython.native
    def _execute(self, command, payload=None):
        fast = getattr(self.transport, 'execute_command', None)
        if fast is None:
            self.wait(self.submit(command, payload))
            return
        if len(command) != 16:
            raise ValueError("GPU command must be 16 bytes")
        command = bytearray(command)
        payload = memoryview(payload) if payload is not None else b''
        if len(payload) > 64:
            raise ValueError("GPU payload exceeds 64 bytes")
        tag = self._tag
        self._tag = (tag + 1) & 65535
        _put16(command, 2, tag)
        self._pending_tag = tag
        self.last_device_error = 0
        error = fast(command, payload, self.timeout_ms)
        self.last_device_error = error
        self._pending_tag = None
        if error:
            raise OSError(error, "Kagura-FB command failed")
'''.splitlines() + ['']
            continue
        if any(isinstance(d,ast.Name) and d.id=='_exclusive' for d in node.decorator_list):
            out+=['    @_exclusive']
        out+=['    @micropython.native']+lines[node.lineno-1:node.end_lineno]+['']
(ROOT/'software/kagura_fb/kagura_native_commands.py').write_text('\n'.join(out),encoding='utf-8')
